"""RAID: decide whether a document was written by a human or generated by a language model."""

import csv
import random
import sys

import orjson
from functools import partial
from pathlib import Path
from tqdm import tqdm
from bottled.constants import DATASETS_DIR
from bottled.datasets.blocklists.raid import BLOCKED_URL_PATTERNS

from . import common

RAW = DATASETS_DIR / "raid" / "raw"
VIEWS = DATASETS_DIR / "raid" / "views"

# The label itself plus every field run_evaluation slices by.
GOLD_FIELDS = ("id", "model", "domain", "attack", "decoding", "repetition_penalty", "source_id")
CHANCE = 0.5


class RAID(common.JsonlDataset):

    BLOCKED_URL_PATTERNS = BLOCKED_URL_PATTERNS


def build_full() -> Path:
    """Write views/full.jsonl: one line per document of train.csv, in file order, holding the model's field and the gold fields in one object for the sampler to split.

    python -c "from bottled.datasets.raid import build_full; build_full()"
    """
    csv.field_size_limit(sys.maxsize)
    src = RAW / "train.csv"
    assert src.exists(), f"missing {src}"
    VIEWS.mkdir(parents=True, exist_ok=True)
    out_path = VIEWS / "full.jsonl"

    n = 0
    n_human = 0
    with src.open("rb") as f, out_path.open("wb") as out, tqdm(total=src.stat().st_size, unit="B", unit_scale=True, desc=f"read {src.name}") as pbar:
        def lines():
            for line in f:
                pbar.update(len(line))
                yield line.decode("utf-8")

        for row in csv.DictReader(lines()):
            # `generation` -> `text` here because the model is shown this
            out.write(orjson.dumps({"text": row["generation"], **{k: row[k] for k in GOLD_FIELDS}}) + b"\n")
            n += 1
            n_human += row["model"] == "human"

    print(f"wrote {n:,} documents to {out_path}: {n_human:,} human, {n - n_human:,} machine")
    return out_path


def _sample_dataset(
    src: Path,
    out_dir: Path,
    seed: int,
    num: int | None = None
) -> tuple[Path, Path, Path]:
    """Shuffle `src` with `seed`, keep the first `num` lines (all if None), and write each kept line as a question line (the document), a gold line (the label and the fields run_evaluation slices by), and an offsets line (line index and byte offset in `src`)."""
    offsets = []  # (line index, byte offset) per source line
    with src.open("rb") as f, tqdm(total=src.stat().st_size, unit="B", unit_scale=True, desc=f"index {src.name}") as pbar:
        while line := f.readline():
            offsets.append((len(offsets), f.tell() - len(line)))
            pbar.update(len(line))
    if num is not None and num > len(offsets):
        raise ValueError(f"asked for {num} lines but {src} has {len(offsets)}")
    n_lines = len(offsets)
    random.Random(seed).shuffle(offsets)
    offsets = offsets[:num]
    wanted = {line_index for line_index, _ in offsets}
    lines = {}
    with src.open("rb") as f:
        for line_index, line in enumerate(tqdm(f, total=n_lines, unit=" lines", unit_scale=True, desc=f"read {src.name}")):
            if line_index in wanted:
                lines[line_index] = line

    tag = f"n{num}_seed{seed}" if num is not None else f"full_seed{seed}"
    q_path = out_dir / f"{tag}_questions.jsonl"
    gt_path = out_dir / f"{tag}_gt.jsonl"
    offsets_path = out_dir / f"{tag}_offsets.jsonl"
    out_dir.mkdir(parents=True, exist_ok=True)
    with q_path.open("wb") as q, gt_path.open("wb") as gt, offsets_path.open("wb") as off:
        for line_index, offset in tqdm(offsets, desc=f"write {tag}"):
            item = orjson.loads(lines[line_index])
            q.write(orjson.dumps({"text": item.pop("text")}) + b"\n")
            gt.write(orjson.dumps(item) + b"\n")
            off.write(orjson.dumps({"line": line_index, "offset": offset}) + b"\n")
    return q_path, gt_path, offsets_path


sample = partial(common.sample, _sample_dataset, VIEWS)

sandbox_input = common.jsonl_sandbox_input

zeroshot_model_input = common.zeroshot_model_input

zeroshot_gold_row = partial(common.zeroshot_gold_row, gold_fields=GOLD_FIELDS)

def parse_zeroshot_pred(text: str | None) -> float:
    """The reply should be a bare confidence in [0, 1], 0 = human and 1 = machine. Anything else scores as chance."""
    try:
        value = float((text or "").strip())
    except ValueError:
        return CHANCE
    return value if 0.0 <= value <= 1.0 else CHANCE

def _score_agg(scores: list[dict]) -> dict:
    # copied from https://github.com/liamdugan/raid/blob/79bcf8ab2ae548791c5eef0ec7d07c7658e454ab/leaderboard/hydrate.py#L161-L194
    # Copyright (c) 2024- Liam Dugan. Licensed under the MIT License: https://github.com/liamdugan/raid/blob/79bcf8ab2ae548791c5eef0ec7d07c7658e454ab/LICENSE
    scores_agg = next(
        (
            s
            for s in reversed(scores)
            if s["domain"] == s["model"] == s["decoding"] == s["repetition_penalty"] == s["attack"] == "all"
        ),
        None,
    )
    if scores_agg is None:
        scores_agg = {
            "_note": (
                "No aggregate score across all settings is reported here as some domains/generator models/decoding"
                " strategies/repetition penalties/adversarial attacks were not included in the submission."
            )
        }

    scores_agg_no_adversarial = next(
        (
            s
            for s in reversed(scores)
            if (s["domain"] == s["model"] == s["decoding"] == s["repetition_penalty"] == "all")
            and (s["attack"] == "none")
        ),
        None,
    )
    if scores_agg_no_adversarial is None:
        scores_agg_no_adversarial = {
            "_note": (
                "No aggregate score across all non-adversarial settings is reported here as some domains/generator"
                " models/decoding strategies/repetition penalties were not included in the submission."
            )
        }

    return {"all": scores_agg, "no_adversarial": scores_agg_no_adversarial}



TARGET_FPRS = [0.05, 0.01]
PER_DOMAIN_TUNING = False


def evaluate_preds(gold_rows: list[dict], preds: list[float], auroc_only: bool = False) -> dict:
    import pandas as pd
    from sklearn.metrics import roc_auc_score
    from raid import run_evaluation

    assert len(preds) <= len(gold_rows), f"{len(preds)} predictions for {len(gold_rows)} lines"
    preds = preds + [CHANCE] * (len(gold_rows) - len(preds))

    n_human = sum(g["model"] == "human" for g in gold_rows)
    if auroc_only:
        return {
            "score_agg": {"all": {"auroc": roc_auc_score([g["model"] != "human" for g in gold_rows], preds)}},
            "auroc_only": True,
            "n_scored": len(preds),
            "distinct_preds": len(set(preds)),
            "n_human": n_human,
            "n_machine": len(gold_rows) - n_human,
        }

    df = pd.DataFrame(gold_rows)
    results = [{"id": g["id"], "score": p} for g, p in zip(gold_rows, preds)]
    out = run_evaluation(
        results, df, target_fpr=TARGET_FPRS, per_domain_tuning=PER_DOMAIN_TUNING
    )

    return {
        "score_agg": _score_agg(out["scores"]),
        **out,
        "per_domain_tuning": PER_DOMAIN_TUNING,
        "n_scored": len(preds),
        "distinct_preds": len(set(preds)),
        "n_human": n_human,
        "n_machine": len(gold_rows) - n_human,
    }


def score_run(dataset_config, out_path: Path) -> dict:
    """Score one run's out file against the sample's gold."""
    ds = RAID(DATASETS_DIR / dataset_config["root"], dataset_config["sample"])
    gold_rows = [zeroshot_gold_row(ds[i]) for i in range(len(ds))]
    with out_path.open(encoding="utf-8") as f:
        preds = [parse_zeroshot_pred(line) for line in f]
    return evaluate_preds(gold_rows, preds)
